const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'The Power of Vaccination: From Smallpox Eradication to COVID-19 in Record Time'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Decorative left bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.5, h: 5.625,
    fill: { color: theme.secondary }
  });

  // Top accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.5, w: 1, h: 0.05,
    fill: { color: theme.accent }
  });

  slide.addText(slideConfig.title, {
    x: 1.0, y: 1.5, w: 8, h: 1.5,
    fontSize: 48, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  slide.addText("1796–2020: A Data-Driven Overview of Vaccine Impact", {
    x: 1.0, y: 3.2, w: 8, h: 0.5,
    fontSize: 24, fontFace: "Georgia",
    color: theme.secondary, bold: false, align: "left"
  });

  slide.addText("Source: Our World in Data", {
    x: 1.0, y: 4.8, w: 8, h: 0.3,
    fontSize: 14, fontFace: "Arial",
    color: "737373", align: "left"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653", secondary: "2a9d8f", accent: "e76f51", light: "e9c46a", bg: "fdfdfd"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

