const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: 'From 100 Years to Under 1 Year: Vaccine Development Is Accelerating'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Page Badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("02", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  // Slide Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Description
  slide.addText("The gap between pathogen identification and vaccine licensure has dramatically collapsed, driven by modern tools like mRNA technology and genomic sequencing.", {
    x: 0.5, y: 1.2, w: 9, h: 0.6,
    fontSize: 16, fontFace: "Arial",
    color: "525252", align: "left"
  });

  // Chart area
  const startX = 2.5;
  const startY = 2.2;
  const rowH = 0.5;
  const maxW = 6.0;

  const data = [
    { label: "Typhoid fever", years: 105, pathogen: 1884, vax: 1989 },
    { label: "Polio", years: 47, pathogen: 1908, vax: 1955 },
    { label: "Ebola", years: 43, pathogen: 1976, vax: 2019 },
    { label: "Hepatitis B", years: 16, pathogen: 1965, vax: 1981 },
    { label: "Measles", years: 10, pathogen: 1953, vax: 1963 },
    { label: "COVID-19", years: 0.9, pathogen: 2020, vax: 2020 }
  ];

  data.forEach((item, index) => {
    const yPos = startY + index * rowH;

    // Label
    slide.addText(item.label, {
      x: 0.5, y: yPos, w: 1.8, h: 0.3,
      fontSize: 14, fontFace: "Arial", bold: true,
      color: theme.primary, align: "right"
    });

    // Bar width proportion
    const barW = (item.years / 105) * maxW;
    const isHighlight = item.label === "COVID-19";

    // Bar shape
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: startX, y: yPos + 0.05, w: barW > 0.05 ? barW : 0.05, h: 0.2,
      fill: { color: isHighlight ? theme.accent : theme.secondary },
      rectRadius: 0.1
    });

    // Value text
    const textW = 1.2;
    slide.addText(item.years < 1 ? "< 1 year" : `${item.years} years`, {
      x: startX + barW + 0.1, y: yPos, w: textW, h: 0.3,
      fontSize: 14, fontFace: "Arial", bold: isHighlight,
      color: isHighlight ? theme.accent : theme.primary, align: "left"
    });

    // Sub-label (dates)
    if (item.years >= 10) {
      slide.addText(`${item.pathogen} - ${item.vax}`, {
        x: startX, y: yPos + 0.25, w: 2, h: 0.2,
        fontSize: 10, fontFace: "Arial",
        color: "737373", align: "left"
      });
    }
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653", secondary: "2a9d8f", accent: "e76f51", light: "e9c46a", bg: "fdfdfd"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

