const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 3,
  title: '100% Case Reduction Achieved for Diphtheria, Polio, and Smallpox in the US'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Page Badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.secondary }
  });
  slide.addText("03", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  // Slide Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.8,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });

  // Data Source
  slide.addText("Data from Roush and Murphy (2007)", {
    x: 0.5, y: 1.2, w: 9, h: 0.3,
    fontSize: 14, fontFace: "Arial",
    color: "737373", align: "left"
  });

  const tableData = [
    [
      { text: "Disease", options: { bold: true, color: "FFFFFF", fill: theme.primary, align: "left", valign: "middle" } },
      { text: "Pre-Vaccine Cases\n(per million/yr)", options: { bold: true, color: "FFFFFF", fill: theme.primary, align: "center", valign: "middle" } },
      { text: "Case Reduction", options: { bold: true, color: "FFFFFF", fill: theme.primary, align: "center", valign: "middle" } },
      { text: "Death Reduction", options: { bold: true, color: "FFFFFF", fill: theme.primary, align: "center", valign: "middle" } }
    ],
    // 100% group
    ["Diphtheria", "158", "100%", "100%"],
    ["Smallpox", "250", "100%", "100%"],
    ["Acute polio", "141", "100%", "100%"],
    ["Measles", "3,044", "99.99%", "100%"],
    ["Rubella", "242", "99.98%", "100%"],
    // High but not 100%
    ["Pertussis", "1,534", "96.6%", "99.7%"],
    // Lower reduction
    [
      { text: "Hepatitis A", options: { color: theme.accent, bold: true } }, 
      { text: "465", options: { color: theme.accent, bold: true } }, 
      { text: "89%", options: { color: theme.accent, bold: true } }, 
      { text: "88.7%", options: { color: theme.accent, bold: true } }
    ],
    [
      { text: "Acute hepatitis B", options: { color: theme.accent, bold: true } }, 
      { text: "273", options: { color: theme.accent, bold: true } }, 
      { text: "83.9%", options: { color: theme.accent, bold: true } }, 
      { text: "83.6%", options: { color: theme.accent, bold: true } }
    ],
    [
      { text: "Pneumococcal", options: { color: theme.accent, bold: true } }, 
      { text: "233", options: { color: theme.accent, bold: true } }, 
      { text: "40.5%", options: { color: theme.accent, bold: true } }, 
      { text: "31.3%", options: { color: theme.accent, bold: true } }
    ]
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 1.6, w: 9,
    colW: [2.5, 2.5, 2.0, 2.0],
    border: { pt: 1, color: "E5E5E5" },
    fill: "FFFFFF",
    fontSize: 14, fontFace: "Arial",
    color: "525252",
    align: "center", valign: "middle",
    margin: 5
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653", secondary: "2a9d8f", accent: "e76f51", light: "e9c46a", bg: "fdfdfd"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

