  index: 8,
  title: "Key Takeaways: Vaccines Have Eliminated Deadly Diseases — But the Job Isn't Done"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Page Badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: "FFFFFF" }
  });
  slide.addText("08", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  // Slide Title
  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.5, w: 9, h: 0.8,
    fontSize: 44, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "left"
  });

  slide.addText("Vaccines Have Eliminated Deadly Diseases — But the Job Isn't Done", {
    x: 0.5, y: 1.2, w: 9, h: 0.4,
    fontSize: 20, fontFace: "Georgia",
    color: theme.light, align: "left"
  });

  const takeaways = [
    "Vaccines achieved 100% elimination of multiple diseases in the US, including polio and smallpox.",
    "Development timelines have collapsed from over 100 years to under 1 year.",
    "Herd immunity protects entire communities, shielding those unable to be vaccinated.",
    "Coverage gaps persist for diseases like pneumococcal disease, hepatitis A, and hepatitis B."
  ];

  takeaways.forEach((point, idx) => {
    const yPos = 2.0 + idx * 0.6;

    // Checkmark icon (simplified with text)
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: yPos + 0.1, w: 0.2, h: 0.2,
      fill: { color: theme.secondary }
    });

    slide.addText("✓", {
      x: 0.5, y: yPos + 0.1, w: 0.2, h: 0.2,
      fontSize: 12, fontFace: "Arial",
      color: "FFFFFF", bold: true, align: "center", valign: "middle"
    });

    slide.addText(point, {
      x: 0.9, y: yPos, w: 8.0, h: 0.4,
      fontSize: 18, fontFace: "Arial",
      color: "F7F7F7", align: "left", valign: "middle"
    });
  });

  // Action block
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 4.4, w: 9.0, h: 0.8,
    fill: { color: "FFFFFF" },
    rectRadius: 0.05
  });

  slide.addText("Priority Action: Improve global access, expand coverage, and build trust in vaccination systems.", {
    x: 0.5, y: 4.4, w: 9.0, h: 0.8,
    fontSize: 18, fontFace: "Arial", bold: true,
    color: theme.primary, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653", secondary: "2a9d8f", accent: "e76f51", light: "e9c46a", bg: "fdfdfd"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

